snippet.code:
type MyAwaited<T> = T extends null | undefined
  ? T
  : T extends object & { then(onfulfilled: infer F, ...args: infer _): unknown }
    ? F extends (value: infer V, ...args: infer _) => unknown
      ? MyAwaited<V>
      : never
    : T;

type Deep = MyAwaited<Promise<Promise<{ id: string }>>>;
// { id: string }

async function mapAsync<T, R>(
  items: T[],
  fn: (item: T) => R | Promise<R>
): Promise<Awaited<R>[]> {
  return Promise.all(items.map(item => fn(item))) as Promise<Awaited<R>[]>;
}

async function loadUsers(ids: string[]) {
  return mapAsync(ids, id => fetch(`/api/users/${id}`).then(r => r.json()));
}
// Return type: Promise<User[]>

const api = {
  async getSession(id: string) {
    const res = await fetch(`/api/session/${id}`);
    return res.json() as Promise<Session>;
  }
};

type SessionResult = Awaited<ReturnType<typeof api.getSession>>;
